import { PLAYABLE_TARGETS, type PlayableTarget } from '../targets';
import type { PlayableCategory, PlayableQuestion } from '../types';

type SourceSeed = string | Readonly<{
  sourceId: string;
  title: string;
  url: string;
  license: string;
}>;

type QuestionSeed = readonly [
  subjectKey: string,
  source: SourceSeed,
  tier: 1 | 2 | 3 | 4 | 5,
  responseEn: string,
  responseEt: string,
  clueEn: string,
  clueEt: string,
  explanationEn: string,
  explanationEt: string,
  variantsEn: readonly string[],
  variantsEt: readonly string[],
];

type CategorySeed = Readonly<{
  nameEn: string;
  nameEt: string;
  relation: string;
  questions: readonly QuestionSeed[];
}>;

const category = (
  nameEn: string,
  nameEt: string,
  relation: string,
  questions: readonly QuestionSeed[],
): CategorySeed => ({ nameEn, nameEt, relation, questions });

